# Writes R/survey_types.R from the survey sheet of one or more 4Mi XLSForms.
#
# The app never reads a questionnaire itself: the question types are baked
# into R/survey_types.R as a plain named vector, sourced with the rest of R/.
# That costs nothing at startup (no file to open, no package to parse it) and
# the generated file shows in a diff exactly which types changed.
#
# From the project root:
#
#   Rscript tools/build_survey_types.R survey.xlsx [more.xlsx ...]
#       Adds the questions the current R/survey_types.R does not have yet.
#       Questions already listed keep their type; a form that disagrees with
#       one is reported, not applied.
#
#   Rscript tools/build_survey_types.R --replace mmc_survey.xlsx [more.xlsx ...]
#       Rebuilds the list from these forms alone. When a name is in more than
#       one form, the first form listed wins.
#
# Then run the tests and regenerate the manifest. The XLSForms do not need to
# stay in the project afterwards.
#
# Not bundled with the app: R/manifest.R lists the files a deployment takes.

args <- commandArgs(trailingOnly = TRUE)
replace <- "--replace" %in% args
paths <- setdiff(args, "--replace")
out <- "R/survey_types.R"
if (length(paths) == 0L) stop("Name at least one XLSForm.", call. = FALSE)
missing <- paths[!file.exists(paths)]
if (length(missing)) stop("No XLSForm at ", paste(missing, collapse = ", "), call. = FALSE)

# XLSForm type -> the type the app's dataset dictionary uses. Types with no
# answer column of their own (groups, notes, audit) and calculations, whose
# result can be a number or text, are left out: those keep the type inferred
# from the export.
map <- c(
  select_one = "select_one", select_one_from_file = "select_one",
  select_multiple = "select_multiple", select_multiple_from_file = "select_multiple",
  rank = "select_multiple",
  integer = "numeric", decimal = "numeric", range = "numeric",
  text = "text", barcode = "text", geopoint = "text", geotrace = "text",
  geoshape = "text", deviceid = "text", phonenumber = "text",
  username = "text", email = "text", simserial = "text", subscriberid = "text",
  date = "date", datetime = "date", time = "date",
  start = "date", end = "date", today = "date"
)

read_form <- function(path) {
  survey <- readxl::read_excel(path, sheet = "survey")
  names(survey) <- tolower(trimws(names(survey)))
  if (!all(c("type", "name") %in% names(survey))) {
    stop(path, ": the survey sheet needs a type and a name column.", call. = FALSE)
  }
  full <- tolower(trimws(survey$type))
  type <- unname(map[sub("[[:space:]].*$", "", full)])
  # "end group" would otherwise read as the `end` timestamp.
  type[grepl("^(begin|end)[ _]+(group|repeat)$", full)] <- NA
  name <- trimws(survey$name)
  keep <- !is.na(type) & !is.na(name) & nzchar(name)
  types <- stats::setNames(type[keep], name[keep])

  clash <- tapply(types, names(types), function(x) length(unique(x)) > 1L)
  if (any(clash)) {
    stop(path, ": names with more than one type: ",
         paste(names(clash)[clash], collapse = ", "), call. = FALSE)
  }
  types[!duplicated(names(types))]
}

types <- if (replace) {
  character(0)
} else {
  if (!file.exists(out)) stop(out, " does not exist yet: use --replace.", call. = FALSE)
  env <- new.env()
  sys.source(out, envir = env)
  env$ak_survey_types()
}
before <- length(types)

for (path in paths) {
  form <- read_form(path)
  shared <- intersect(names(form), names(types))
  differ <- shared[form[shared] != types[shared]]
  if (length(differ)) {
    message(path, ": kept the existing type of ", length(differ), " question(s) it ",
            "types differently: ", paste0(differ, " (", form[differ], ")", collapse = ", "))
  }
  added <- form[!names(form) %in% names(types)]
  if (length(added)) {
    message(path, ": adds ", length(added), ": ", paste(names(added), collapse = ", "))
  }
  types <- c(types, added)
}

body <- paste0("    ", sprintf("%-14s", paste0('"', names(types), '"')), ' = "', types, '"')
lines <- c(
  "# Generated by tools/build_survey_types.R from the survey sheet of the 4Mi",
  "# XLSForms. Do not edit by hand: rerun the script when the questionnaire changes.",
  "",
  "#' Question Types From the 4Mi Questionnaires",
  "#'",
  "#' Used first by ak_dataset_dictionary(); a question not listed here has its",
  "#' type inferred from the export.",
  "#'",
  "#' @return A named character vector: names are question codes, values",
  "#'   `select_one`, `select_multiple`, `numeric`, `text` or `date`.",
  "ak_survey_types <- function() {",
  "  c(",
  paste0(body, c(rep(",", length(body) - 1L), "")),
  "  )",
  "}"
)
writeLines(lines, out)
message("Wrote ", length(types), " question types to ", out,
        if (!replace) paste0(" (", length(types) - before, " new)"), ": ",
        paste(names(table(types)), table(types), sep = " ", collapse = ", "))
